action.code:
size_t h1 = ckh->hash1(key);
size_t h2 = ckh->hash2(key);
size_t idx1 = h1 & (ckh->capacity - 1);
size_t idx2 = h2 & (ckh->capacity - 1);

// Try to insert into primary slot
if (ckh->table[idx1].key == nullptr) {
    ckh->table[idx1].key = key;
    ckh->table[idx1].data = data;
    ckh->count++;
    return false;
}

// Try to insert into secondary slot
if (ckh->table[idx2].key == nullptr) {
    ckh->table[idx2].key = key;
    ckh->table[idx2].data = data;
    ckh->count++;
    return false;
}

// Both slots occupied - perform cuckoo eviction
const void* curr_key = key;
const void* curr_data = data;
size_t curr_idx = idx1;

for (size_t i = 0; i < ckh->capacity; i++) {
    // Swap current item with slot occupant
    std::swap(ckh->table[curr_idx].key, curr_key);
    std::swap(ckh->table[curr_idx].data, curr_data);

    // Check if we just placed the last displaced item
    if (curr_key == nullptr) {
        ckh->count++;
        return false;
    }

    // Find new position for displaced item
    h1 = ckh->hash1(curr_key);
    h2 = ckh->hash2(curr_key);
    idx1 = h1 & (ckh->capacity - 1);
    idx2 = h2 & (ckh->capacity - 1);

    // Choose the other slot (not the one we just came from)
    curr_idx = (curr_idx == idx1) ? idx2 : idx1;

    // If the chosen slot is empty, place item there
    if (ckh->table[curr_idx].key == nullptr) {
        ckh->table[curr_idx].key = curr_key;
        ckh->table[curr_idx].data = curr_data;
        ckh->count++;
        return false;
    }
}

// Cycle detected - need to grow table
return true;
// END_CODE

